import React, { useState, useRef, useEffect } from 'react'
import { 
  MessageSquare, 
  X, 
  Send, 
  Minimize2, 
  Maximize2, 
  ThumbsUp, 
  ThumbsDown,
  Sparkles,
  User,
  Shield,
  Bot,
  ArrowRight,
  ClipboardList,
  Search,
  HelpCircle,
  HeadphonesIcon
} from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'
import { chatbotService } from '../services/api'
import { useAuth } from '../contexts/AuthContext'
import toast from 'react-hot-toast'

import Button from './shared/Button'

const ChatbotWidget = () => {
  const { user } = useAuth()
  const [isOpen, setIsOpen] = useState(false)
  const [isMinimized, setIsMinimized] = useState(false)
  const [messages, setMessages] = useState([
    {
      type: 'bot',
      content: 'Hello! I am your Citizen Sentinel, the official AI assistant for the Local Government System BPLO. How can I guide your application today?'
    }
  ])
  const [inputMessage, setInputMessage] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [sessionId, setSessionId] = useState(`session_${Date.now()}`)
  const messagesEndRef = useRef(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages, isOpen])

  const handleSendMessage = async (e, customMessage = null) => {
    if (e) e.preventDefault()
    const userMessage = customMessage || inputMessage.trim()
    if (!userMessage || isLoading) return

    setInputMessage('')
    setMessages(prev => [...prev, { type: 'user', content: userMessage }])
    setIsLoading(true)

    try {
      const response = await chatbotService.sendMessage({
        message: userMessage,
        sessionId: sessionId
      })

      const { response: botContent, escalated, intent } = response.data.data
      
      setMessages(prev => [...prev, {
        type: 'bot',
        content: botContent,
        escalated: escalated,
        intent: intent
      }])

      if (escalated) {
        toast.info('Your query has been escalated to our staff for manual review.')
      }
    } catch (error) {
      setMessages(prev => [...prev, {
        type: 'bot',
        content: 'I apologize, but my connection to the municipal registry was interrupted. Please try again or contact us at 09811568676.'
      }])
    } finally {
      setIsLoading(false)
    }
  }

  const quickActions = [
    { label: 'Check Status', icon: Search, query: 'What is my permit status?' },
    { label: 'Requirements', icon: ClipboardList, query: 'What documents do I need?' },
    { label: 'Fee Inquiry', icon: HelpCircle, query: 'How much does it cost?' },
    { label: 'Human Help', icon: HeadphonesIcon, query: 'I want to talk to a human agent' }
  ]

  if (!isOpen) {
    return (
      <motion.button
        initial={{ scale: 0, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(true)}
        className="fixed bottom-6 right-6 z-50 w-16 h-16 bg-primary-600 text-white rounded-2xl shadow-premium flex items-center justify-center transition-all group overflow-hidden"
      >
        <div className="absolute inset-0 bg-gradient-to-br from-white/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
        <MessageSquare className="w-8 h-8 relative z-10" />
      </motion.button>
    )
  }

  return (
    <motion.div 
      initial={{ opacity: 0, y: 100, scale: 0.9 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, y: 100, scale: 0.9 }}
      className={`fixed bottom-6 right-6 z-50 w-[400px] max-w-[calc(100vw-3rem)] bg-white rounded-3xl shadow-2xl border border-brand-100 flex flex-col overflow-hidden transition-all duration-300 ${isMinimized ? 'h-16' : 'h-[600px]'}`}
    >
      {/* Premium Header */}
      <div className="bg-brand-900 text-white p-5 flex items-center justify-between relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-r from-primary-600/20 to-transparent pointer-events-none" />
        <div className="flex items-center space-x-3 relative z-10">
          <div className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center backdrop-blur-md">
            <Bot className="w-6 h-6 text-primary-400" />
          </div>
          <div>
            <h3 className="font-display font-bold text-sm tracking-tight">Citizen Sentinel</h3>
            <div className="flex items-center space-x-1.5">
              <span className="w-1.5 h-1.5 bg-success-500 rounded-full animate-pulse" />
              <span className="text-[10px] font-bold text-brand-300 uppercase tracking-widest">System Online</span>
            </div>
          </div>
        </div>
        <div className="flex items-center space-x-1 relative z-10">
          <button onClick={() => setIsMinimized(!isMinimized)} className="p-2 hover:bg-white/10 rounded-lg transition-colors">
            {isMinimized ? <Maximize2 className="w-4 h-4" /> : <Minimize2 className="w-4 h-4" />}
          </button>
          <button onClick={() => setIsOpen(false)} className="p-2 hover:bg-white/10 rounded-lg transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>
      </div>

      {!isMinimized && (
        <>
          {/* Chat Canvas */}
          <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-brand-50/30 scrollbar-hide">
            <AnimatePresence mode="popLayout">
              {messages.map((msg, idx) => (
                <motion.div 
                  key={idx}
                  initial={{ opacity: 0, x: msg.type === 'user' ? 20 : -20, y: 10 }}
                  animate={{ opacity: 1, x: 0, y: 0 }}
                  className={`flex ${msg.type === 'user' ? 'justify-end' : 'justify-start'}`}
                >
                  <div className={`flex items-end space-x-2 max-w-[85%] ${msg.type === 'user' ? 'flex-row-reverse space-x-reverse' : ''}`}>
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${
                      msg.type === 'user' ? 'bg-primary-100 text-primary-600' : 'bg-brand-900 text-white'
                    }`}>
                      {msg.type === 'user' ? <User className="w-4 h-4" /> : <Shield className="w-4 h-4 text-primary-400" />}
                    </div>
                    <div className={`px-4 py-3 rounded-2xl text-sm leading-relaxed shadow-sm ${
                      msg.type === 'user' 
                        ? 'bg-primary-600 text-white rounded-tr-none' 
                        : 'bg-white text-brand-900 border border-brand-100 rounded-tl-none'
                    }`}>
                      {msg.content}
                      {msg.escalated && (
                        <div className="mt-2 pt-2 border-t border-brand-50 flex items-center text-[10px] font-bold text-warning-600 uppercase tracking-tight">
                          <Sparkles className="w-3 h-3 mr-1.5" /> Escalated to human Reviewer
                        </div>
                      )}
                    </div>
                  </div>
                </motion.div>
              ))}
              {isLoading && (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex justify-start">
                  <div className="bg-white border border-brand-100 rounded-2xl px-4 py-3 flex space-x-1.5">
                    {[0, 1, 2].map(i => (
                      <div key={i} className="w-1.5 h-1.5 bg-brand-200 rounded-full animate-bounce" style={{ animationDelay: `${i * 0.1}s` }} />
                    ))}
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
            <div ref={messagesEndRef} />
          </div>

          {/* Quick Action Tray */}
          <div className="px-6 py-4 bg-white border-t border-brand-50">
            <div className="grid grid-cols-2 gap-2">
              {quickActions.map((action, i) => (
                <button
                  key={i}
                  onClick={() => handleSendMessage(null, action.query)}
                  className="flex items-center space-x-2 p-2.5 rounded-xl border border-brand-100 hover:border-primary-200 hover:bg-primary-50 transition-all text-left group"
                >
                  <action.icon className="w-4 h-4 text-brand-400 group-hover:text-primary-600" />
                  <span className="text-[11px] font-bold text-brand-600 uppercase tracking-tight">{action.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Input Terminal */}
          <form onSubmit={handleSendMessage} className="p-6 bg-white border-t border-brand-100">
            <div className="relative group">
              <input
                type="text"
                value={inputMessage}
                onChange={(e) => setInputMessage(e.target.value)}
                placeholder="Ask your sentinel..."
                className="w-full bg-brand-50/50 border-2 border-transparent focus:border-primary-500 focus:bg-white rounded-2xl px-5 py-4 text-sm font-medium outline-none transition-all pr-14 group-hover:bg-brand-50"
              />
              <button
                type="submit"
                disabled={isLoading || !inputMessage.trim()}
                className="absolute right-2 top-2 bottom-2 w-12 bg-primary-600 hover:bg-primary-700 disabled:opacity-50 text-white rounded-xl flex items-center justify-center transition-all shadow-lg shadow-primary-500/20"
              >
                <Send className="w-5 h-5" />
              </button>
            </div>
            <p className="mt-3 text-[10px] text-center text-brand-400 font-bold uppercase tracking-widest">
              Institutional AI • 256-bit Encrypted
            </p>
          </form>
        </>
      )}
    </motion.div>
  )
}

export default ChatbotWidget

